/**
 * Рассчитывает профит-фактор на основе данных о сделках.
 *
 * Profit Factor = Общая прибыль от успешных сделок / Общие убытки от убыточных сделок.
 *
 * @param {Array} trades - Массив объектов с данными о сделках, содержащими ключ "profit" (прибыль/убыток).
 * @returns {number} - Значение профит-фактора.
 */
export const calculateProfitFactor = (trades) => {
  // Разделяем сделки на прибыльные и убыточные
  const totalProfit = trades
    .filter((trade) => trade.profit > 0) // Только прибыльные сделки
    .reduce((sum, trade) => sum + trade.profit, 0); // Сумма прибылей

  const totalLoss = trades
    .filter((trade) => trade.profit < 0) // Только убыточные сделки
    .reduce((sum, trade) => sum + Math.abs(trade.profit), 0); // Сумма убытков

  // Если убытков нет, профит-фактор бесконечен (идеальная стратегия)
  if (totalLoss === 0) return Infinity;

  // Расчет профит-фактора
  return totalProfit / totalLoss;
};
