import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import styles from './Trade.module.css'
import { Deposit } from '../components/Deposit'
import { Tracker } from '../components/Tracker/Tracker'
import { Strategys } from '../components/Strategys'
import { SystemStatus } from '../components/SystemStatus'
import { AccountModal } from '../components/AccountModal'
import { AccountInformation } from '../components/AccountInformation'
import { useDispatch, useSelector } from "react-redux";
import { fetchUserDataRequest } from "../../../../redux/slices/userDataSlice"; // Убедись, что путь корректный
import { TestBlock } from '../components/TestBlock/TestBlock';

export const Trade = () => {
  const dispatch = useDispatch();
  const [showModal, setShowModal] = useState(false);
  const [accountNumber, setAccountNumber] = useState('');
  const user = useSelector((state) => state.login.user)
  const userData = useSelector((state) => state.userData?.data)

  useEffect(() => {
    if (!userData) {
      // Можно выбрать: показать модалку или просто ничего не делать
      setShowModal(true);
      return;
    }

    if (!userData.realAccountNumber) {
      setShowModal(true);

    } else {
      setAccountNumber(userData.realAccountNumber);
    }
  }, []);

  // Когда accountNumber обновился — делаем запрос к серверу
  useEffect(() => {
    if (accountNumber) {
      dispatch(fetchUserDataRequest(user.id));
    }
  }, [accountNumber, dispatch]);

  const handleSaveAccount = (number) => {
    setAccountNumber(number); // это автоматически вызовет useEffect выше
    localStorage.setItem('realAccountNumber', number);
    setShowModal(false);
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };

  const handleSettingsClick = () => {
    setShowModal(true); // Открываем модал по кнопке "настроить"
  };


  return (
        <>
          {showModal && (
            <AccountModal
              title={'Торговый счет'}
              description={'Основной счет с Вашим депозитом. Чтобы начать зарабатывать введите номер Вашего торгового счета. Если у Вас еще нет номера — создайте торговый счет'}
              inputField={true}
              placeholder={'Введите номер торгового счёта'}
              firstButton={'Готово'}
              secondButton={'Создать торговый счёт'}
              onSave={handleSaveAccount}
              onClose={handleCloseModal}
              numberName={'realAccountNumber'}
              accountType={'real'}
            />
          )}
      <div style={{ filter: showModal ? 'blur(3px)' : 'none' }}>
      <div className={styles.header}>
      <h1 className={styles.title}>
        Торговый счет
      </h1>
      <AccountInformation 
        onSettingsClick={handleSettingsClick} 
        accountNumber={accountNumber}
        accountName={'realAccountNumber'}
      />
      </div>
      {accountNumber ? <TestBlock/> : null }
      <Deposit statistics={true} real={true} cssVariant='alt'/>
      <SystemStatus />
      <Tracker />
      <Strategys/>
      </div>
    </>
  )
}
