import React, { useState } from "react";
import styles from "./StrategyMenu.module.css";

export const StrategyMenu = ({
  strategies,
  selectedStrategy,
  onStrategyChange,
}) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  // Открываем меню при наведении
  const handleMouseEnter = () => setIsMenuOpen(true);

  // Закрываем меню, когда курсор уходит
  const handleMouseLeave = () => setIsMenuOpen(false);

  return (
    <div
      className={styles.menu_wrapper}
      onMouseEnter={handleMouseEnter} // Открытие меню при наведении
      onMouseLeave={handleMouseLeave} // Закрытие меню при уходе курсора
    >
      {/* Кнопка для отображения текущей стратегии */}
      <button
        className={`${styles.button} ${isMenuOpen ? styles.active : ""}`}
        aria-expanded={isMenuOpen}
        aria-controls="strategy-list"
      >
        <span className={styles.button_text}>Торговая стратегия</span>
      </button>

      {/* Меню со списком стратегий */}
      <ul className={styles.menu} id="strategy-list" aria-hidden={!isMenuOpen}>
        {strategies.map(([key, strategy], index) => (
          <li key={index} className={styles.menu_item}>
            <button
              className={`${styles.menu_link} ${
                selectedStrategy === strategy.name ? styles.selected : ""
              }`}
              tabIndex={isMenuOpen ? 0 : -1}
              onClick={() => {
                onStrategyChange([key, strategy]);
              }}
            >
              {strategy.name}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};
