import React from 'react'
import {
  XAxis,
  YAxis,
  Tooltip,
  AreaChart,
  Area,
  CartesianGrid,
} from "recharts";
import styles from "./LineChart.module.css"

const CustomTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    return (
      <div
        style={{
          backgroundColor: "#222",
          border: "1px solid #444",
          borderRadius: "4px",
          padding: "1px",
          color: "#fff",
          fontSize: "4px",
        }}
      >
        <p>{`${label}`}</p>
        <p>{`Цена: ${payload[0].value}`}</p>
      </div>
    );
  }
  return null;
};

export const LineChart = ({data, id, color}) => {

  const pair = "EUR/USD"
  return (
      <div className={styles.container}>
        <div className={styles.chart_info}>
          <div className={styles.pair_title}>
            <span className={styles.pair_name}>{pair}</span>
            <span className={styles.pair_value}>1.0889</span>
          </div>
          <div className={styles.pair_info}>
            <span className={styles.pair_indicator}>-0.24% 0.0007</span>
            <span className={styles.pair_high_rate}>H 1.0917</span>
            <span className={`${styles.pair_low_rate} ${styles.rate_active}`}>L 1.0887</span>
          </div>
        </div>
      <AreaChart
        width={205}
        height={130}
        data={data}
        syncId={`${id}`}
        margin={{
          top: 0,
          right: 10,
          left: 0,
          bottom: -5,
        }}
      >

        {/* Сетка */}
        <CartesianGrid 
          strokeDasharray="3 3"  
          stroke="transparent"
          fill={`${color}`}
        />

        {/* Оси */}
        <XAxis
          dataKey="name"
          tick={{ fontSize: 10, fill: "#ccc" }}
          stroke="#ccc"
        />
        {/*<YAxis orientation="right"
          tick={{ fontSize: 10, fill: "#ccc" }}
          stroke="#ccc"
        />*/}

        {/* Подсказка */}
        <Tooltip content={<CustomTooltip />} />

        {/* График */}
        <Area
          type="monotone"
          dataKey="pv"
          stroke="white"
          fill={`${color}`}
          strokeWidth={1}
        />
      </AreaChart>
      </div>
  )
}
