import React, { useState, useEffect } from "react";
import Marquee from "react-fast-marquee";
import styles from "./IndexString.module.css";

export const IndexString = () => {
  const initialItems = [
    {
      id: 1,
      symbol: "USD/JPY",
      price: 151.45,
      change: 0,
      percentageChange: 0,
      icon: "🇯🇵",
    },
    {
      id: 2,
      symbol: "EUR/USD",
      price: 1.0812,
      change: 0,
      percentageChange: 0,
      icon: "🇪🇺",
    },
    {
      id: 3,
      symbol: "GBP/USD",
      price: 1.2705,
      change: 0,
      percentageChange: 0,
      icon: "🇬🇧",
    },
    {
      id: 4,
      symbol: "AAPL",
      price: 193.89,
      change: 0,
      percentageChange: 0,
      icon: "🍎",
    },
    {
      id: 5,
      symbol: "TSLA",
      price: 258.6,
      change: 0,
      percentageChange: 0,
      icon: "🚗",
    },
    {
      id: 6,
      symbol: "XAU/USD",
      price: 2415.3,
      change: 0,
      percentageChange: 0,
      icon: "🪙",
    },
    {
      id: 7,
      symbol: "XAG/USD",
      price: 28.73,
      change: 0,
      percentageChange: 0,
      icon: "🪙",
    },
    {
      id: 8,
      symbol: "BTC/USD",
      price: 68420.0,
      change: 0,
      percentageChange: 0,
      icon: "🪙",
    },
    {
      id: 9,
      symbol: "ETH/USD",
      price: 5000.0,
      change: 0,
      percentageChange: 0,
      icon: "🪙",
    },
    {
      id: 10,
      symbol: "XRP/USD",
      price: 0.41,
      change: 0,
      percentageChange: 0,
      icon: "🪙",
    },
  ];

  const [items, setItems] = useState(initialItems);

  const updatePrices = () => {
    setItems((prevItems) =>
      prevItems.map((item) => {
        let newPrice = parseFloat(
          (item.price + (Math.random() - 0.5) * 10).toFixed(2),
        );
        newPrice = Math.max(newPrice, 0);

        const change = parseFloat((newPrice - item.price).toFixed(2));
        const percentageChange = parseFloat(
          ((change / item.price) * 100).toFixed(2),
        );

        const priceClass =
          change > 0
            ? `${styles.price} ${styles.green}`
            : change < 0
              ? `${styles.price} ${styles.red}`
              : styles.price;
        const changeClass =
          change > 0
            ? `${styles.change} ${styles.green}`
            : change < 0
              ? `${styles.change} ${styles.red}`
              : styles.change;
        const percentageClass =
          change > 0
            ? `${styles.percentageChange} ${styles.green}`
            : change < 0
              ? `${styles.percentageChange} ${styles.red}`
              : styles.percentageChange;

        return {
          ...item,
          price: newPrice,
          change,
          percentageChange,
          priceClass,
          changeClass,
          percentageClass,
        };
      }),
    );
  };

  useEffect(() => {
    const interval = setInterval(updatePrices, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <Marquee
      className={styles.items_wrap}
      gradient={false} // Отключаем градиент по краям
      speed={50} // Скорость прокрутки
      pauseOnHover // Останавливаем при наведении
    >
      {items.map((item) => (
        <div key={item.id}>
          <span className={styles.separator}></span>
          <div className={styles.item}>
            <span className={styles.icon}>{item.icon}</span>
            <span className={styles.symbol}>{item.symbol}</span>
            <span className={item.priceClass || styles.price}>
              {item.price}
            </span>
            <span className={item.changeClass || styles.change}>
              {item.change > 0 ? `+${item.change}` : item.change}
            </span>
            <span className={item.percentageClass || styles.percentageChange}>
              (
              {item.percentageChange > 0
                ? `+${item.percentageChange}%`
                : `${item.percentageChange}%`}
              )
            </span>
          </div>
        </div>
      ))}
    </Marquee>
  );
};

