import React, { useState } from "react";
import styles from "./Strategies.module.css";

export const Strategies = () => {
  const [activeCardId, setActiveCardId] = useState(null); // ID активной карточки
  const [isFlipped, setIsFlipped] = useState(false);

  // Данные о карточках
  const cardsData = [
    {
      id: 1,
      frontLabel: "ТС: ОБ30",
      backDescription:
        "Алгоритмическая торговая стратегия разработана с целью поиска точки входа на 1-минутном таймфрейме, позволяя алгоритму ювелирно входить в сделку с увеличенным соотношением risk/reward. В стратегии используется ордерблок, структурный анализ, сетка фибоначчи.",
      position: { x: "-100%", y: "-125%" },
    },
    {
      id: 2,
      frontLabel: "ТС: VSA_ML",
      backDescription:
        "Торговая стратегия разработана с применением машинного обучения и инновационных гибридных моделей нейросети Название в частности. Для принятия торговых решений модель анализирует профили объемов, зоны ликвидности, выявляет аномальные аномальный объемы. Для усиления трейдов используются индикаторы A/D-line, ATR, RSI.",
      position: { x: "175%", y: "-100%" },
    },
    {
      id: 3,
      frontLabel: "ТС: TSA_ML",
      backDescription:
        "Торговая стратегия разработана с применением машинного обучения и инновационных гибридных моделей, обученных предсказывать направление движения котировки. ",
      position: { x: "200%", y: "110%" },
    },
    {
      id: 4,
      frontLabel: "ТС: в разработке",
      backDescription: "в разработке",
      position: { x: "-40%", y: "150%" },
    },
    {
      id: 5,
      frontLabel: "ТС: в разработке",
      backDescription: "в разработке",
      position: { x: "-250%", y: "20%" },
    },
  ];

  const handleCardClick = (cardId) => {
    setActiveCardId(activeCardId === cardId ? null : cardId); // Переключение состояния
    setIsFlipped(!isFlipped);
  };

  const handleClose = () => {
    setActiveCardId(null);
    setIsFlipped(false);
  };

  return (
    <>
      <div className={styles.title}>
        <h1 className={styles.title_text}>Стратегии</h1>
      </div>
      {isFlipped && <div className={styles.overlay} onClick={handleClose} />}
      <div className={styles.absolute_container}>
        {cardsData.map((card) => (
          <div
            key={card.id}
            className={`${styles.absolute_item} ${activeCardId === card.id ? styles.flipped : ""}`}
            onClick={() => handleCardClick(card.id)}
            style={{
              transform:
                activeCardId === card.id
                  ? `translate(${20}%, ${-25}%) scale(1.25) rotateY(180deg)`
                  : `translate(${card.position.x}, ${card.position.y})`,
              transition: "transform 0.6s ease-in-out",
            }}
          >
            <div className={styles.front}>
              <span className={styles.label}>{card.frontLabel}</span>
            </div>
            <div className={styles.back}>
              <span className={styles.description}>{card.backDescription}</span>
            </div>
          </div>
        ))}
        <div className={styles.brainCenter}>
          <span className={styles.label}>Мозговой ИИ-центр</span>
        </div>
      </div>
    </>
  );
};
