import React, { useState }  from 'react'
import { Efficiency } from '../Efficiency'
import { AutoTracking } from '../AutoTracking/AutoTracking';
import { useSelector } from 'react-redux';

import styles from './Deposit.module.css'
import altStyles from './DepositAlt.module.css';

export const Deposit = ({statistics, real, showDepositCurrency = true, autoTrackingVisibility, cssVariant}) => {
  const isVisible = autoTrackingVisibility ?? true;
  const appliedStyles = cssVariant === 'alt' ? altStyles : styles;
  const [activeProfit, setActiveProfit] = useState('today'); // 'today' или 'total'
  const [isAutoTrackingEnabled, setIsAutoTrackingEnabled] = useState(false);
  const userData = useSelector((state) => state.userData?.data);

  const handleSelect = (type) => {
    setActiveProfit(type);
  };

  const handleToggleChange = (value) => {
    setIsAutoTrackingEnabled(value);
  };

  const totalProfit =
  userData?.accountInfo?.equity != null && userData?.accountInfo?.balance != null
    ? (userData.accountInfo.equity - userData.accountInfo.balance).toFixed(2)
    : 'N/A';
  //const profitToday = ;
  const profitAmount = activeProfit === 'today' ? (userData ? userData.profitToday : 'N/A') : (totalProfit);

  let profitToday = 'N/A'
  let profitTotal = 'N/A'

  if (userData) {

  profitToday = userData.profitToday / userData.balance * 100;
  profitToday = Math.floor(profitToday * 100) / 100;

  profitTotal = userData.profitTotal / userData.balance * 100;
  profitTotal = Math.floor(profitTotal * 100) / 100;
  }

  return (
    <div className={appliedStyles.container}>
      {isVisible ? <AutoTracking onToggleChange={handleToggleChange}/> : null}
      <div className={appliedStyles.columnContainer}>
        <div className={appliedStyles.rowContainer}>
          <div className={appliedStyles.header}>
            <h2 className={appliedStyles.tytle}>Депозит {real ? '(Основной)' : '(Демо)'}</h2>
            <h3 className={appliedStyles.inUse}>Задействовано: {userData ? userData.partInTrade : 'N/A'}%</h3>
          </div>
          <div className={appliedStyles.depositInformation}>
            <h3 className={appliedStyles.depositCurrency}>{userData?.accountInfo?.currency ?? 'N/A'}</h3>
            <h3 className={appliedStyles.depositVolume}>{userData?.accountInfo?.balance ?? 'N/A'}</h3> 
          </div>

        </div>
        
        <div className={appliedStyles.rowContainer}>
          <div className={appliedStyles.profitInformation}>
            <div
              className={`${appliedStyles.profitToday} ${
                activeProfit === 'today' ? appliedStyles.active : appliedStyles.inactive
              }`}
              onClick={() => handleSelect('today')}
            >
              <span className={appliedStyles.profitTodayTitle}>Сегодня</span>
              <span className={appliedStyles.profitTodayValue}>+{profitToday}%</span>
            </div>

            <div
              className={`${appliedStyles.profitTotal} ${
                activeProfit === 'total' ? appliedStyles.active : appliedStyles.inactive
              }`}
              onClick={() => handleSelect('total')}
            >
              <span className={appliedStyles.profitTodayTitle}>Всего</span>
              <span className={appliedStyles.profitTodayValue}>{profitTotal}%</span>
            </div>
          </div>
           <div className={appliedStyles.depositInformation}>
            {showDepositCurrency ? <h3 className={appliedStyles.depositCurrency}>{userData.accountInfo.currency}</h3> : null}
            <div className={appliedStyles.profitАmount}>{profitAmount}</div>
          </div>  
        </div>
      </div>          
      {statistics ?       
      <div className={appliedStyles.statistics}>
        <Efficiency 
          title={'Количество трейдов'}
          /*view={'#1D1D1D'}*/
          value={3}
        />
        <Efficiency 
          title={'Прибыль/убыток'}
          /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
          value={null}
        />
        <Efficiency 
          title={'Коэффициент Шарпа'}
          /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
          value={null}
        />
      </div> : null}

    </div>
  );
};