import { useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { useNavigate } from "react-router-dom";
import { fetchUserDataRequest } from "../../../../../redux/slices/userDataSlice";
import styles from './TestBlock.module.css';

export const TestBlock = () => {
  const accountInfo = useSelector((state) => state.userData.data.accountInfo);
  const userId = useSelector((state) => state.login?.user.id || localStorage.getItem("userId"));
  const dispatch = useDispatch();
  const navigate = useNavigate();

  useEffect(() => {
    if (!userId) return;

    // Сразу делаем первый запрос
    dispatch(fetchUserDataRequest(userId));

    // Запускаем интервал
    const interval = setInterval(() => {
      dispatch(fetchUserDataRequest(userId));
    }, 1000);

    // Очищаем интервал при размонтировании
    return () => clearInterval(interval);
  }, [userId, dispatch]);

  if (!accountInfo) {
    return <div className={styles.empty}>Нет данных по счёту</div>;
  }

  const totalProfit = accountInfo.positions
  ? accountInfo.positions.reduce((sum, pos) => sum + (Number(pos.profit) || 0), 0)
  : 0;

  return (
    <div className={styles.accountBlock}>
      <h2>Информация о счёте</h2>
      <div className={styles.infoGrid}>
        <div><b>Логин:</b> {accountInfo.login}</div>
        <div><b>Имя:</b> {accountInfo.name}</div>
        <div><b>Сервер:</b> {accountInfo.server}</div>
        <div><b>Валюта:</b> {accountInfo.currency}</div>
        <div><b>Кредитное плечо:</b> {accountInfo.leverage}</div>
        <div><b>Баланс:</b> {accountInfo.balance}</div>
        <div><b>Эквити:</b> {accountInfo.equity}</div>
        <div><b>Маржа:</b> {accountInfo.margin}</div>
        <div><b>Свободная маржа:</b> {accountInfo.free_margin}</div>
        <div><b>Обновлено:</b> {new Date(accountInfo.updatedAt).toLocaleString()}</div>
      </div>

      <h3>Открытые позиции</h3>
      {accountInfo.positions && accountInfo.positions.length > 0 ? (
        <table className={styles.positionsTable}>
          <thead>
            <tr>
              <th>Тикет</th>
              <th>Символ</th>
              <th>Тип</th>
              <th>Объём</th>
              <th>Цена открытия</th>
              <th>SL</th>
              <th>TP</th>
              <th>Профит</th>
            </tr>
          </thead>
          <tbody>
            {accountInfo.positions.map(pos => (
              <tr key={pos.ticket}>
                <td>{pos.ticket}</td>
                <td>{pos.symbol}</td>
                <td>{pos.type === 0 ? "Buy" : "Sell"}</td>
                <td>{pos.volume}</td>
                <td>{pos.price_open}</td>
                <td>{pos.sl}</td>
                <td>{pos.tp}</td>
                <td className={pos.profit < 0 ? styles.negative : styles.positive}>
                  {pos.profit > 0 ? `+${pos.profit}` : pos.profit}
                </td>
              
              </tr>
            ))}
              {/* Итоговая строка */}
              <tr>
                <td colSpan={7}></td>
                <td className={totalProfit < 0 ? styles.negative : styles.positive} style={{fontWeight: 'bold'}}>
                  {totalProfit > 0 ? `+${totalProfit.toFixed(2)}` : totalProfit.toFixed(2)}
                </td>
              </tr>
          </tbody>
        </table>
      ) : (
        <div className={styles.empty}>Нет открытых позиций</div>
      )}
    </div>
  );
};