import { Strategies } from "./pages/strategies/Strategies";
import { PrivateRoute } from "./utils/PrivateRoute";
import { ToastContainer } from "react-toastify";
import { logout, fetchLoginSuccess } from "./redux/slices/loginSlice"; // путь к твоему слайсу
import { fetchUserDataApi } from "./api/authApi";
import "react-toastify/dist/ReactToastify.css";

function App() {

  const dispatch = useDispatch();

  useEffect(() => {
    const checkToken = async () => {
      const token = localStorage.getItem("token");
      const user = localStorage.getItem("user");
      if (token && user) {
        // Пробуем получить данные пользователя с этим токеном
        try {
          // Например, запрос к /user-data (или /me, если реализуешь)
          const { data, status } = await fetchUserDataApi(JSON.parse(user).id);
          if (status === 200) {
            // Всё ок, обновляем Redux (если нужно)
            dispatch(fetchLoginSuccess({ user: JSON.parse(user), token }));
          } else {
            // Токен невалиден или истёк
            dispatch(logout());
          }
        } catch (e) {
          dispatch(logout());
        }
      } else {
        dispatch(logout());
      }
    };

    checkToken();
  }, [dispatch]);


  return (
    <>
      {/*<StockBackground /> {/* Добавлен фон */}
      <BrowserRouter>
        <Header />
        <Routes>
          {/* Главная страница с секциями */}
          <Route
            path="/"
            element={
              <div className="main-conteiner">
                {/* Полоса вверху экрана */}
                <div className="top-line" />
                <section id="home">
                  <Home />
                </section>
                <section id="trades">
                  <Trades />
                </section>
                <section id="technologies">
                  <Technologies />
                </section>
                <section id="strategies">
                  <Strategies />
                </section>
                <section id="safety">
                  <Safety />
                </section>
                <section id="сonnect">
                  <Connect />
                </section>
                <section id="affiliateProgram">
                  <AffiliateProgram />
                </section>
              </div>
            }
          />

          {/* Отдельные страницы */}
          {/*<Route
            path="/profile"
            element={
              logged_in_user["isSuperUser"] === 1 ? (
                <SuperUser />
              ) : (
                <RegularUser />
              )
            }
          />*/}
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route element={<PrivateRoute />}>
          <Route path="/profile" element={<RegularUser />} />
            {/* можно добавить и другие защищённые маршруты */}
          </Route>
        </Routes>
        <ToastContainer />
      </BrowserRouter>
    </>
  );
}

export default App;
