import React from 'react'
import {
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  AreaChart,
  Area,
  ReferenceLine,
  ResponsiveContainer,
} from "recharts";

import styles from './ProfitabilityChart.module.css'

function generateTradingData({
  startDate = "2020-01-01",
  months = 72, // 6 лет
  startValue = 1000,
  baseGrowth = 0.015, // базовый рост в месяц (1.5%)
  volatility = 0.07, // максимальное отклонение (7%)
  drawdownChance = 0.2 // вероятность просадки
} = {}) {
  const data = [];
  let currentValue = startValue;
  let currentDate = new Date(startDate);

  for (let i = 0; i < months; i++) {
    // Случайный прирост или просадка
    let change = baseGrowth + (Math.random() * volatility * 2 - volatility);

    // Иногда делаем просадку
    if (Math.random() < drawdownChance) {
      change = -Math.abs(change * (0.8 + Math.random() * 0.4)); // -80%..-120% от изменения
    }

    // Обновляем значение
    currentValue = +(currentValue * (1 + change)).toFixed(2);

    // Добавляем объект в результат
    data.push({
      date: currentDate.toISOString().split("T")[0],
      value: currentValue,
      timeframe: "monthly"
    });

    // Переход к следующему месяцу
    currentDate.setMonth(currentDate.getMonth() + 1);
  }

  return data;
}

const CustomTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    return (
      <div
        style={{
          backgroundColor: "#222",
          border: "1px solid #444",
          borderRadius: "8px",
          padding: "10px",
          color: "#fff",
          fontSize: "10px",
        }}
      >
        <p>{`${label}`}</p>
        <p>{`Цена: ${payload[0].value}`}</p>
      </div>
    );
  }
  return null;
};


export const ProfitabilityChart = () => {

  const data = generateTradingData({
    startDate: "2020-01-01",
    months: 71,
    startValue: 10000,
    baseGrowth: 0.07, // 2% в месяц
    volatility: 0.14,
    drawdownChance: 0.27
  }); 

  return (
    <>
    <div className={styles.container}>
          {/* График */}
          <ResponsiveContainer width="100%" height={400} debounce={50}>
          <AreaChart

            data={data}
            margin={{ top: 30, right: 0, left: 15, bottom: 20 }}
          >
            {/* Определение градиента */}
            <defs>
              <linearGradient id="colorPv" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="green" stopOpacity={0.5} />
                <stop offset="95%" stopColor="green" stopOpacity={0.1} />
              </linearGradient>
            </defs>
    
            {/* Сетка */}
            <CartesianGrid strokeDasharray="3 3" stroke="#444" />
    
            {/* Оси */}
            <XAxis
              dataKey="date"
              tick={{ fontSize: 10, fill: "#ccc" }}
              stroke="#ccc"
            />
            <YAxis
              orientation="right"
              tick={{ fontSize: 10, fill: "#ccc" }}
              stroke="#ccc"
            />
    
            {/* Подсказка */}
            <Tooltip content={<CustomTooltip />} />
    
            {/* Область графика */}
            <Area
              type="monotone"
              dataKey="value"
              stroke="green"
              fill="url(#colorPv)"
              strokeWidth={1}
              activeDot={{ r: 5, stroke: "green", strokeWidth: 2, fill: "#fff" }} // Активная точка при наведении
            />
    
            {/* Добавление пунктирных линий */}
            <ReferenceLine
              x={null} // Будет динамически обновляться через Tooltip
              stroke="green"
              strokeDasharray="5 5"
              strokeWidth={1}
            />
            <ReferenceLine
              y={null} // Будет динамически обновляться через Tooltip
              stroke="green"
              strokeDasharray="5 5"
              strokeWidth={1}
            />
          </AreaChart>
          </ResponsiveContainer>
          </div>
          </>
  )
}
