/**
 * Рассчитывает коэффициент Шарпа на основе данных о доходности.
 *
 * Коэффициент Шарпа измеряет риск-адаптированную доходность портфеля:
 * Sharpe Ratio = (Средняя доходность - Безрисковая ставка) / Стандартное отклонение доходности.
 *
 * @param {Array} data - Массив объектов с данными, содержащими ключ "pv" (значение портфеля).
 * @param {number} annualRiskFreeRate - Годовая безрисковая ставка (например, 0.02 для 2%).
 * @returns {number} - Значение коэффициента Шарпа.
 */
export const calculateSharpeRatio = (data, annualRiskFreeRate = 2) => {
  // Переводим годовую безрисковую ставку в месячную
  const riskFreeRateMonthly = annualRiskFreeRate / 100 / 12;

  // Преобразуем данные в массив доходностей
  const returns = data.map((entry, index, array) => {
    if (index === 0) return 0; // Первая точка не имеет предыдущей
    return (entry.pv - array[index - 1].pv) / array[index - 1].pv;
  });

  // Удаляем первую точку (она равна 0)
  const validReturns = returns.slice(1);

  // Средняя доходность и стандартное отклонение
  const meanReturn =
    validReturns.reduce((sum, r) => sum + r, 0) / validReturns.length;
  const stdDev = Math.sqrt(
    validReturns.reduce((sum, r) => sum + Math.pow(r - meanReturn, 2), 0) /
      validReturns.length,
  );

  // Коэффициент Шарпа
  return (meanReturn - riskFreeRateMonthly) / stdDev;
};
