import React, { useState, useEffect, useRef } from "react";
import "./Home.css";
import AISpheresScene from "../../components/custom/AISpheresScene";
/* ========================================================================== */
/* Компоненты разработки                                                      */
/* ========================================================================== */

export function Home() {
  // Состояние для хранения позиции прокрутки
  const [scrollY, setScrollY] = useState(0);

  // Обработчик прокрутки
  useEffect(() => {
    const handleScroll = () => {
      setScrollY(window.scrollY); // Обновляем позицию прокрутки
    };

    // Добавляем обработчик события прокрутки
    window.addEventListener("scroll", handleScroll);

    // Очищаем обработчик при размонтировании компонента
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  // Вычисляем смещение для блоков в зависимости от прокрутки
  const getBlock1Transform = () => {
    // Блок 1 изначально смещен вправо (translateX(15vw))
    // При прокрутке вниз он будет двигаться к центру (translateX(0))
    const maxScroll = 275; // Максимальная прокрутка, при которой достигается центр
    const offset = Math.min(scrollY / maxScroll, 1); // Нормализуем прокрутку (0..1)
    const translateX = 15 * offset;
    return `translateX(${translateX}vw)`;
  };

  const getBlock2Transform = () => {
    // Блок 2 изначально смещен влево (translateX(-9vw))
    // При прокрутке вниз он будет двигаться к центру (translateX(0))
    const maxScroll = 275; // Максимальная прокрутка, при которой достигается центр
    const offset = Math.min(scrollY / maxScroll, 1); // Нормализуем прокрутку (0..1)
    const translateX = -16.3 * offset;
    return `translateX(${translateX}vw)`;
  };

  return (
    <>
      {/* Переключатель для элементов разработки */}
      {/*<ToggleDevElements />*/}

      {/* Контейнер для блоков №1 и №2 */}
      <div className="blocks-container--1-2">
        {/* Блок №1 */}
        <div
          className="block--1"
          style={{
            transform: getBlock1Transform(), // Применяем динамическое смещение
          }}
        >
          {/* Содержимое блока */}
          <h1 className="home-text__title home-text__title--xl">
            Forward Trading
          </h1>
        </div>

        {/* Блок №2 */}
        <div
          className="block--2"
          style={{
            transform: getBlock2Transform(), // Применяем динамическое смещение
          }}
        >
          {/* Содержимое блока */}
          <h4 className="home-text__title home-text__title--lg">
            Торговля будущего. Сегодня
          </h4>
        </div>
      </div>

      {/* Контейнер для блоков №3 и №4 */}
      <div className="blocks-container--3-4">
        {/* Блок №4 */}
        <div className="block--3">
          {/* Содержимое блока */}
          {/*<AISpheresScene />*/}
        </div>

        {/* Блок №4 */}
        <div className="block--4">
          {/* Содержимое блока */}
          <h4 className="home-text__title home-text__title--md text-block--center">
            Мы уважаем Ваше время и готовы взять на себя часть забот по
            диверсификации Вашего депозита
          </h4>
        </div>
      </div>
    </>
  );
}
