import React, { useState } from 'react';
import { ToggleTabs } from '../../components/ToggleTabs'
import { ProfitabilityChart } from '../ProfitabilityChart'

import styles from './Tracker.module.css'

export const Tracker = () => {
  const [viewSelector, setViewSelector] = useState('График');
  const [timeframeSelector, setTimeframeSelector] = useState('День');

  
  return (
      <div className={styles.container}>
        <div className={styles.header}>
          <h2 className={styles.tytle}>Трекер</h2>
        </div>
        <div className={styles.toggleContainer}>
          <ToggleTabs
            options={['График', 'Список']}
            onChange={(value) => setViewSelector(value)}
          />
          <ToggleTabs
            options={['День', 'Неделя', 'Месяц', '6 Месяцев', 'Год']}
            onChange={(value) => setTimeframeSelector(value)}
          />
        </div>
        <ProfitabilityChart />
      </div>
  )
}
