import { createSlice } from "@reduxjs/toolkit";

const initialState = {
  user: null,
  isLoading: false,
  error: null,
  isRegistered: false,
};

const registerSlice = createSlice({
  name: "register",
  initialState,
  reducers: {
    fetchRegisterRequest: (state) => {
      state.isLoading = true;
      state.error = null;
    },
    fetchRegisterSuccess: (state, action) => {
      state.isLoading = false;
      state.user = action.payload;
      state.isRegistered = true; // Устанавливаем регистрацию
      state.error = null;
    },
    fetchRegisterFailure: (state, action) => {
      state.isLoading = false;
      state.isRegistered = false; // Сбрасываем регистрацию
      state.error = action.payload;
    },
    resetRegister(state) {
      state.isRegistered = false; // Сброс регистрациb
    },
  },
});

export const {
  fetchRegisterRequest,
  fetchRegisterSuccess,
  fetchRegisterFailure,
  resetRegister,
} = registerSlice.actions;

export default registerSlice.reducer;
