import React, { useEffect, useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { toast, Bounce } from "react-toastify";
import { fetchLoginRequest } from "../../../redux/slices/loginSlice"
import { users } from "../../../backend_data";
import { Loading } from "../../Loading"
import "./Login.css"

import { DashboardHeader } from "../../headers/DashboardHeader";
import { DashboardFooter } from '../../footers/DashboardFooter';

export function Login() {
  const { isLoggedIn } = useSelector((state) => state.login);
  const { isLoading } = useSelector((state) => state.login);


  const [user, setUser] = useState({
    email: "",
    password: "",
  });

  const [errors, setErrors] = useState([]);

  const [submitting, setSubmitting] = useState(false);

  const navigate = useNavigate();

  const dispatch = useDispatch();

  useEffect(() => {
    
    if (isLoggedIn) {
      navigate("/profile");
    }
  }, [isLoggedIn, navigate]);

  const loginUser = async (event) => {
    event.preventDefault();
    console.log(user)
    dispatch(fetchLoginRequest(user));
  }
  
  const emailValidation = (errors, "email");
  const passwordValidation = (errors, "password");
  
  return (
    <>
    <div className="containerLogin">  {/* переделать  */}
      <DashboardHeader />
      {isLoading ? (
        <Loading />
      ) : (
        <div className="login-container">
          <div className="login-card">
            <div className="login-header">
              <h2 className="login-title">Вход в аккаунт</h2>
              <p className="login-subtitle">Используйте свои данные для входа</p>
            </div>
  
            <form className="login-form" onSubmit={(e) => loginUser(e)}>
              <div className="form-group">
                <label htmlFor="email" className="form-label">Электронный адрес</label>
                <input
                  type="email"
                  id="email"
                  onChange={(e) => setUser({ ...user, email: e.target.value })}
                  value={user.email}
                  name="email"
                  className="form-input"
                  placeholder="example@domain.com"
                />
                {emailValidation}
              </div>
  
              <div className="form-group">
                <label htmlFor="password" className="form-label">Пароль</label>
                <input
                  type="password"
                  id="password"
                  onChange={(e) => setUser({ ...user, password: e.target.value })}
                  value={user.password}
                  name="password"
                  className="form-input"
                  placeholder="••••••••"
                />
                {passwordValidation}
              </div>
  
              {submitting ? (
                <div className="spinner">Загрузка...</div>
              ) : (
                <>
                  <button type="submit" className="login-button">
                    Войти
                  </button>
                  <div className="register-link">
                    <p className="login-link"> {/* переделать это сделать css */}
                      Присоединяйтесь к AI Trading <Link to="/register"> Зарегистрироваться</Link>
                    </p>
                  </div>
                </>
              )}
            </form>
          </div>
        </div>
      )}
      <DashboardFooter/>
      </div>
    </>
)};