import React, { useState, useEffect, useRef } from 'react'
import { LineChart } from "../LineChart"
import styles from "./MultiChartPanel.module.css"

export const MultiChartPanel = ({ data }) => {
  const [activeChart, setActiveChart] = useState(null)
  const [transform, setTransform] = useState({ x: 0, y: 0 }) // смещение
  const chartRefs = useRef({})
  const containerRef = useRef()

  const handleChartClick = (id) => {
    if (activeChart === id) {
      // Повторный клик — сброс
      setActiveChart(null)
      return
    }

    const chart = chartRefs.current[id]
    const container = containerRef.current

    if (chart && container) {
      const chartRect = chart.getBoundingClientRect()
      const containerRect = container.getBoundingClientRect()

      // Центр контейнера
      const containerCenterX = containerRect.left + containerRect.width / 2
      const containerCenterY = containerRect.top + containerRect.height / 2

      // Центр графика
      const chartCenterX = chartRect.left + chartRect.width / 2
      const chartCenterY = chartRect.top + chartRect.height / 2

      // Смещение графика к центру
      const offsetX = containerCenterX - chartCenterX
      const offsetY = containerCenterY - chartCenterY

      setTransform({ x: offsetX, y: offsetY })
      setActiveChart(id)
    }
  }

  // Клик вне — сброс
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (activeChart !== null) {
        const chart = chartRefs.current[activeChart]
        if (chart && !chart.contains(e.target)) {
          setActiveChart(null)
        }
      }
    }

    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [activeChart])

  const renderChart = (id, color) => {
    const isActive = activeChart === id
    const style = isActive
      ? {
          transform: `translate(${transform.x}px, ${transform.y}px) scale(3.0)`,
          zIndex: 10,
        }
      : {}
    return (
      <div
        key={id}
        ref={(el) => (chartRefs.current[id] = el)}
        className={`${styles.chartWrapper} ${
          isActive ? styles.active : activeChart ? styles.inactive : ''
        }`}
        style={style}
        onClick={(e) => {
          e.stopPropagation()
          handleChartClick(id)
        }}
      >
        <LineChart data={data} id={id} color={color} />
      </div>
    )
  }

  return (
    <div className={styles.container} ref={containerRef}>
      {/*<div className={styles.column}>*/}
        {renderChart(1, "#B00020")}
        {renderChart(2, "green")}
        {renderChart(3, "#B00020")}
        {renderChart(4, "green")}
      {/*</div>*/}
      {/*<div className={styles.column}>*/}
        {renderChart(5, "#B00020")}
        {renderChart(6, "green")}
        {renderChart(7, "#B00020")}
        {renderChart(8, "green")}
      {/*</div>*/}
      {/*<div className={styles.column}>*/}
        {renderChart(9, "green")}
        {renderChart(10, "green")}
        {renderChart(11, "#B00020")}
        {renderChart(12, "#B00020")}
      {/*</div>*/}
    </div>
  )
}