// ДАННЫЙ МЕТОД ГРУППИРУЕТ ДАННЫЕ ПО ДНЯМ, МЕСЯЦАМ ИЛИ ГОДАМ

function groupData(data, groupBy = "day") {
  const grouped = {};

  for (const [timestamp, value] of Object.entries(data)) {
    const date = new Date(parseInt(timestamp) * 1000);
    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, "0");
    const day = String(date.getUTCDate()).padStart(2, "0");

    let groupKey;

    switch (groupBy) {
      case "year":
        groupKey = year;
        break;
      case "month":
        groupKey = `${year}-${month}`;
        break;
      case "day":
      default:
        groupKey = `${year}-${month}-${day}`;
    }

    if (!grouped[groupKey]) {
      grouped[groupKey] = [];
    }

    grouped[groupKey].push(value);
  }

  return grouped;
}

// ДАННЫЙ МЕТОД ПРОИЗВОДИТ СУММУ ИЛИ ВЫЧИСЛЯЕТ СРЕДНЕЕ У ДАННЫХ, СГРУППИРОВАННЫХ ПО ДНЯМ, МЕСЯЦАМ ИЛИ ГОДАМ ПРИ ПОМОЩИ ПРЕДЫДУЩЕГО МЕТОДА

function groupAndAggregate(data, groupBy = "day", aggFn = "sum") {
  const grouped = groupData(data, groupBy);
  const result = {};

  for (const [key, values] of Object.entries(grouped)) {
    if (aggFn === "sum") {
      result[key] = values.reduce((a, b) => a + b, 0);
    } else if (aggFn === "avg") {
      result[key] = values.reduce((a, b) => a + b, 0) / values.length;
    }
    // Add other aggregations as needed
  }

  return result;
}

// ДАННЫЙ МЕТОД СОРТИРУЕТ ЭЛЕМЕНТЫ ОБЪЕКТА (СЛОВАРЯ) ПО КЛЮЧУ (ДАТЕ) И ВОЗВРАЩАЕТ ПОСЛЕДНИЕ N ПАР КЛЮЧ-ЗНАЧЕНИЕ:

function returnLastNKeyValuePairs(dateObj, number_of_pairs) {
  const sortedEntries = Object.entries(dateObj).sort(
    ([dateA], [dateB]) => new Date(dateA) - new Date(dateB),
  );

  // 2. Get last N entries (most recent dates)
  const lastN = (n) => Object.fromEntries(sortedEntries.slice(-n));

  // Example usage:

  const lastNPairs = lastN(number_of_pairs);

  return lastNPairs;
}

