import React from "react";
import {
  XAxis,
  YAxis,
  Tooltip,
  ComposedChart,
  Bar,
  Line,
  ResponsiveContainer,
  Rectangle,
  CartesianGrid,
} from "recharts";
import styles from "./Histogram.module.css";

const CustomTooltip = ({ active, payload, label }) => {
  return null;
};

export const Histogram = ({ data }) => {
  return (
    <div className={styles.container}>
      {/* Адаптивный контейнер */}
      <ResponsiveContainer width={870} height={100}>
        <ComposedChart
          data={data}
          syncId="anyId"
          margin={{
            top: 0,
            right: 0,
            left: 20,
            bottom: 20,
          }}
        >
          {/* Градиент для столбцов */}
          <defs>
            <linearGradient id="colorPv" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#ffd700" stopOpacity={1} />
              <stop offset="95%" stopColor="#ffd700" stopOpacity={0.1} />
            </linearGradient>
          </defs>

          {/* Сетка */}
          <CartesianGrid strokeDasharray="3 3" stroke="#444" />

          {/* Оси */}
          <XAxis dataKey="name" tick={{ fontSize: 12 }} />
          <YAxis orientation="right" tick={{ fontSize: 12 }} />

          {/* Подсказка */}
          <Tooltip content={<CustomTooltip />} />

          {/* Столбцы гистограммы */}
          <Bar
            dataKey="pv"
            fill="url(#colorPv)"
            activeBar={<Rectangle fill="rgba(56, 197, 240, 0.66)" />}
          />

          {/* Линия распределения */}
          <Line
            type="monotone" // Плавная линия
            dataKey="pv" // Ключ данных для линии
            stroke="#ff7300" // Цвет линии
            strokeWidth={2} // Толщина линии
            dot={false} // Отключаем точки на линии
          />
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
};
